package view;

import database.DBConnection;
import javax.swing.*;import javax.swing.table.DefaultTableModel;import java.awt.*;import java.sql.*;

public class ComplaintsFrame extends JFrame {
 private final int residentId;private final DefaultTableModel model=new DefaultTableModel(new String[]{"ID","Title","Category","Status","Created"},0){public boolean isCellEditable(int r,int c){return false;}};
 public ComplaintsFrame(int residentId){this.residentId=residentId;setTitle("Maintenance complaints");setSize(780,520);setLocationRelativeTo(null);setDefaultCloseOperation(DISPOSE_ON_CLOSE);JPanel p=new JPanel(new BorderLayout(12,12));p.setBorder(BorderFactory.createEmptyBorder(18,18,18,18));p.setBackground(new Color(250,245,235));setContentPane(p);JLabel title=new JLabel("Maintenance & Complaints");title.setFont(new Font("Serif",Font.BOLD,25));p.add(title,BorderLayout.NORTH);JTable table=new JTable(model);table.setRowHeight(26);p.add(new JScrollPane(table),BorderLayout.CENTER);JPanel bottom=new JPanel(new FlowLayout(FlowLayout.RIGHT));bottom.setOpaque(false);JButton add=LoginFrame.button("NEW COMPLAINT"),refresh=new JButton("Refresh");bottom.add(refresh);bottom.add(add);p.add(bottom,BorderLayout.SOUTH);add.addActionListener(e->createComplaint());refresh.addActionListener(e->load());load();setVisible(true);}
 private void createComplaint(){JTextField title=new JTextField(),description=new JTextField();JComboBox<String> category=new JComboBox<>(new String[]{"Plumbing","Electrical","Cleaning","Security","Lift","Other"});JPanel form=new JPanel(new GridLayout(0,1,5,5));form.add(new JLabel("Short title"));form.add(title);form.add(new JLabel("Category"));form.add(category);form.add(new JLabel("Description"));form.add(description);if(JOptionPane.showConfirmDialog(this,form,"Submit complaint",JOptionPane.OK_CANCEL_OPTION)!=JOptionPane.OK_OPTION)return;if(title.getText().trim().isEmpty()){JOptionPane.showMessageDialog(this,"Please enter a title.");return;}String sql="INSERT INTO \"A-partment\".complaints(resident_id,title,description,category,status) VALUES(?,?,?,?,'PENDING')";try(Connection c=DBConnection.getConnection();PreparedStatement s=c.prepareStatement(sql)){s.setInt(1,residentId);s.setString(2,title.getText().trim());s.setString(3,description.getText().trim());s.setString(4,(String)category.getSelectedItem());s.executeUpdate();JOptionPane.showMessageDialog(this,"Complaint submitted.");load();}catch(Exception ex){LoginFrame.showDbError(ex);}}
 private void load(){model.setRowCount(0);String sql="SELECT complaint_id,title,category,status,created_at FROM \"A-partment\".complaints WHERE resident_id=? ORDER BY complaint_id DESC";try(Connection c=DBConnection.getConnection();PreparedStatement s=c.prepareStatement(sql)){s.setInt(1,residentId);try(ResultSet r=s.executeQuery()){while(r.next())model.addRow(new Object[]{r.getInt(1),r.getString(2),r.getString(3),r.getString(4),r.getTimestamp(5)});}}catch(Exception ex){LoginFrame.showDbError(ex);}}
}
